import * as http from 'http';
import * as crypto from 'crypto';

interface TemplateContext {
  [key: string]: unknown;
}

class SecureTemplateEngine {
  private allowedPaths = new Set<string>();
  private contextStore = new Map<string, TemplateContext>();

  constructor() {
    this.allowedPaths.add('user.name');
    this.allowedPaths.add('user.email');
    this.allowedPaths.add('order.id');
    this.allowedPaths.add('order.total');
    this.allowedPaths.add('site.title');
  }

  registerContext(sessionId: string, ctx: TemplateContext): void {
    this.contextStore.set(sessionId, ctx);
  }

  private createSandbox(data: Record<string, unknown>): Map<string, unknown> {
    // Create a flat Map from allowed paths for safe lookup
    const flatMap = new Map<string, unknown>();
    for (const path of this.allowedPaths) {
      const parts = path.split('.');
      let current: unknown = data;
      let valid = true;
      for (const part of parts) {
        if (current === null || current === undefined || typeof current !== 'object') {
          valid = false;
          break;
        }
        if (!Object.prototype.hasOwnProperty.call(current, part)) {
          valid = false;
          break;
        }
        current = (current as Record<string, unknown>)[part];
      }
      if (valid && typeof current !== 'function' && typeof current !== 'object') {
        flatMap.set(path, current);
      }
    }
    return flatMap;
  }

  private resolvePath(sandbox: Map<string, unknown>, path: string): unknown {
    return sandbox.get(path) ?? '';
  }

  render(template: string, sessionId: string): string {
    const ctx = this.contextStore.get(sessionId);
    if (!ctx) return template;

    const sandbox = this.createSandbox(ctx);

    // Safe regex-based interpolation - only allows alphanumeric paths
    return template.replace(/\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g, (match, path) => {
      // Validate path is in allowlist
      if (!this.allowedPaths.has(path)) {
        return '[BLOCKED]';
      }
      const value = this.resolvePath(sandbox, path);
      if (typeof value === 'function') return '[BLOCKED]';
      return String(value);
    });
  }
}

class NotificationService {
  private engine = new SecureTemplateEngine();
  private templates = new Map<string, string>();

  constructor() {
    this.templates.set('welcome', 'Hello {{user.name}}, welcome to {{site.title}}!');
    this.templates.set('order', 'Order {{order.id}} total: {{order.total}}');
  }

  registerTemplate(name: string, template: string): void {
    // Only allow safe template patterns
    const unsafePatterns = /(<script|javascript:|on\w+=|eval|Function|require|import|process)/i;
    if (unsafePatterns.test(template)) {
      throw new Error('Template contains unsafe patterns');
    }
    // Validate template only contains allowed paths
    const usedPaths = [...template.matchAll(/\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g)].map(m => m[1]);
    for (const path of usedPaths) {
      if (!this.engine['allowedPaths'].has(path)) {
        throw new Error(`Template references disallowed path: ${path}`);
      }
    }
    this.templates.set(name, template);
  }

  prepareNotification(sessionId: string, templateName: string, data: Record<string, unknown>): string {
    this.engine.registerContext(sessionId, data);
    const template = this.templates.get(templateName);
    if (!template) return 'Template not found';
    return this.engine.render(template, sessionId);
  }
}

class RequestHandler {
  private notificationService = new NotificationService();
  private sessions = new Map<string, { userId: string; role: string }>();

  handleRequest(req: http.IncomingMessage, body: string): string {
    const url = new URL(req.url || '/', `http://${req.headers.host}`);
    const path = url.pathname;

    if (path === '/api/register-template' && req.method === 'POST') {
      return this.handleRegisterTemplate(body);
    }
    if (path === '/api/render' && req.method === 'POST') {
      return this.handleRender(body);
    }
    return JSON.stringify({ error: 'Not found' });
  }

  private handleRegisterTemplate(body: string): string {
    try {
      const { name, template } = JSON.parse(body);
      if (typeof name !== 'string' || typeof template !== 'string') {
        return JSON.stringify({ error: 'Invalid input' });
      }
      if (name.length > 64 || template.length > 1024) {
        return JSON.stringify({ error: 'Input too long' });
      }
      this.notificationService.registerTemplate(name, template);
      return JSON.stringify({ success: true });
    } catch (e: any) {
      return JSON.stringify({ error: e.message });
    }
  }

  private handleRender(body: string): string {
    try {
      const { sessionId, templateName, data } = JSON.parse(body);
      if (typeof templateName !== 'string') {
        return JSON.stringify({ error: 'Invalid input' });
      }
      // Validate `data` is a plain, non-null object before use
      if (data === null || typeof data !== 'object' || Array.isArray(data)) {
        return JSON.stringify({ error: 'Invalid input' });
      }
      const sid = (typeof sessionId === 'string' && sessionId.length > 0) ? sessionId : crypto.randomUUID();
      const result = this.notificationService.prepareNotification(sid, templateName, data);
      return JSON.stringify({ result });
    } catch (e: any) {
      return JSON.stringify({ error: e.message });
    }
  }
}

const handler = new RequestHandler();
const MAX_BODY_SIZE = 64 * 1024; // 64 KB request body limit
const server = http.createServer((req, res) => {
  let body = '';
  let size = 0;
  let aborted = false;
  req.on('data', chunk => {
    if (aborted) return;
    size += chunk.length;
    if (size > MAX_BODY_SIZE) {
      aborted = true;
      res.writeHead(413, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Payload too large' }));
      req.destroy();
      return;
    }
    body += chunk;
  });
  req.on('end', () => {
    if (aborted) return;
    const result = handler.handleRequest(req, body);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(result);
  });
});

server.listen(3000);
